static void dash_log_font_glyph(const char *scope,
                                const lv_font_t *font,
                                uint32_t codepoint,
                                const char *label)
{
  lv_font_glyph_dsc_t dsc;
  bool ok;

  if (font == NULL)
    {
      LVGL_APP_LOGW(HOME_VIEW_TAG,
                    "%s font glyph skipped font=%s cp=U+%04lx label=%s",
                    scope, DASH_FONT_CJK_NAME,
                    (unsigned long)codepoint,
                    label != NULL ? label : "");
      return;
    }

  ok = lv_font_get_glyph_dsc(font, &dsc, codepoint, 0);
  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "%s font glyph font=%s ptr=%p cp=U+%04lx label=%s ok=%d placeholder=%u resolved=%p adv=%u box=%ux%u",
                scope,
                DASH_FONT_CJK_NAME,
                font,
                (unsigned long)codepoint,
                label != NULL ? label : "",
                ok ? 1 : 0,
                (unsigned int)dsc.is_placeholder,
                dsc.resolved_font,
                (unsigned int)dsc.adv_w,
                (unsigned int)dsc.box_w,
                (unsigned int)dsc.box_h);
}

