static lvgl_app_home_hotspot_t *dash_find_hotspot(
  lvgl_app_page_home_view_t *view,
  lvgl_app_home_component_id_t component)
{
  if (view == NULL)
    {
      return NULL;
    }

  for (unsigned int i = 0; i < view->hotspot_count; i++)
    {
      if (view->hotspots[i].id == component)
        {
          return &view->hotspots[i];
        }
    }

  return NULL;
}

static void dash_update_selection_label(lvgl_app_page_home_view_t *view,
                                        const char *name)
{
  const lv_font_t *font;

  if (view == NULL || view->selection_label == NULL)
    {
      return;
    }

  if (name == NULL || name[0] == '\0')
    {
      lv_obj_add_flag(view->selection_label, LV_OBJ_FLAG_HIDDEN);
      return;
    }

  lv_label_set_text_fmt(view->selection_label, "已选中  %s", name);
  font = lv_obj_get_style_text_font(view->selection_label, LV_PART_MAIN);
  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "selection label show name=%s obj=%p font=%p text_w=%ld text_h=%ld",
                name,
                view->selection_label,
                font,
                (long)lv_obj_get_width(view->selection_label),
                (long)lv_obj_get_height(view->selection_label));
  lv_obj_align(view->selection_label, LV_ALIGN_BOTTOM_MID, 0,
               -dash_scale_y(view, 36));
  lv_obj_remove_flag(view->selection_label, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(view->selection_label);
}

static void dash_update_selection_box(lvgl_app_page_home_view_t *view,
                                      lv_obj_t *target)
{
  int32_t x;
  int32_t y;
  int32_t w;
  int32_t h;

  if (view == NULL || view->selection_box == NULL)
    {
      return;
    }

  if (target == NULL)
    {
      lv_obj_add_flag(view->selection_box, LV_OBJ_FLAG_HIDDEN);
      LVGL_APP_LOGI(HOME_VIEW_TAG, "selection box hide");
      return;
    }

  x = lv_obj_get_x(target);
  y = lv_obj_get_y(target);
  w = lv_obj_get_width(target);
  h = lv_obj_get_height(target);

  lv_obj_set_pos(view->selection_box, x - 3, y - 3);
  lv_obj_set_size(view->selection_box, w + 6, h + 6);
  lv_obj_remove_flag(view->selection_box, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(view->selection_box);
  lv_obj_invalidate(view->selection_box);

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "selection box show target=%p box=%p pos=%ld,%ld size=%ldx%ld",
                target,
                view->selection_box,
                (long)(x - 3),
                (long)(y - 3),
                (long)(w + 6),
                (long)(h + 6));
}

static void dash_apply_selected_component(
  lvgl_app_page_home_view_t *view,
  lvgl_app_home_component_id_t component)
{
  lvgl_app_home_hotspot_t *selected = NULL;

  if (view == NULL)
    {
      return;
    }

  for (unsigned int i = 0; i < view->hotspot_count; i++)
    {
      if (view->hotspots[i].obj == NULL)
        {
          continue;
        }

      if (view->hotspots[i].id == component)
        {
          selected = &view->hotspots[i];
          lv_obj_add_state(view->hotspots[i].obj, LV_STATE_CHECKED);
        }
      else
        {
          lv_obj_remove_state(view->hotspots[i].obj, LV_STATE_CHECKED);
        }
    }

  view->selected_component = component;
  dash_update_selection_box(view, selected != NULL ? selected->obj : NULL);
  dash_update_selection_label(view, selected != NULL ? selected->name : NULL);
  if (selected != NULL)
    {
      LVGL_APP_LOGI(HOME_VIEW_TAG, "feedback selected %s",
                    selected->name);
    }
}

static void dash_hotspot_event(lv_event_t *event)
{
  lvgl_app_home_hotspot_t *hotspot =
    (lvgl_app_home_hotspot_t *)lv_event_get_user_data(event);
  lvgl_app_page_home_view_t *view;
  lv_event_code_t code = lv_event_get_code(event);
  lv_point_t point = { 0, 0 };
  lv_indev_t *indev = lv_indev_active();

  if (hotspot == NULL || hotspot->view == NULL ||
      (code != LV_EVENT_PRESSED && code != LV_EVENT_CLICKED))
    {
      return;
    }

  view = hotspot->view;
  if (indev != NULL)
    {
      lv_indev_get_point(indev, &point);
    }

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "hotspot event code=%s id=%d name=%s obj=%p pos=%ld,%ld size=%ldx%ld point=%ld,%ld",
                dash_event_code_name(code),
                (int)hotspot->id,
                hotspot->name,
                hotspot->obj,
                (long)lv_obj_get_x(hotspot->obj),
                (long)lv_obj_get_y(hotspot->obj),
                (long)lv_obj_get_width(hotspot->obj),
                (long)lv_obj_get_height(hotspot->obj),
                (long)point.x,
                (long)point.y);
  if (code == LV_EVENT_PRESSED)
    {
      dash_apply_selected_component(view, hotspot->id);
      return;
    }

  if (view->cb.on_component_selected != NULL)
    {
      view->cb.on_component_selected(hotspot->id, view->user);
    }
  else
    {
      dash_apply_selected_component(view, hotspot->id);
    }
}
