        {
          LVGL_APP_LOGE(HOME_VIEW_TAG,
                        "image source missing id=%u name=%s",
                        (unsigned int)image, name);
          return NULL;
        }
    }
  else
    {
      LVGL_APP_LOGI(HOME_VIEW_TAG,
                    "image path validate id=%u name=%s path=%s",
                    (unsigned int)image, name, path);

      fs_res = lv_fs_open(&file, path, LV_FS_MODE_RD);
      if (fs_res != LV_FS_RES_OK)
        {
          struct stat st;
          const char *real_path = path;
          int fd;

          if (path[0] >= 'A' && path[0] <= 'Z' && path[1] == ':')
            {
              real_path = path + 2;
            }

          errno = 0;
          fd = open(real_path, O_RDONLY);
          LVGL_APP_LOGE(HOME_VIEW_TAG,
                        "image open failed path=%s real=%s res=%d fd=%d errno=%d",
                        path, real_path, (int)fs_res, fd, errno);
          if (fd >= 0)
            {
              (void)close(fd);
            }

          if (stat("/rodata", &st) < 0)
            {
              LVGL_APP_LOGE(HOME_VIEW_TAG, "stat /rodata failed errno=%d",
                            errno);
            }
          else
            {
              LVGL_APP_LOGI(HOME_VIEW_TAG, "/rodata mode=0%lo",
                            (unsigned long)st.st_mode);
            }

          return NULL;
        }

      (void)lv_fs_close(&file);
      src = path;
      LVGL_APP_LOGI(HOME_VIEW_TAG,
                    "image path ready id=%u name=%s path=%s",
                    (unsigned int)image, name, path);
    }

  zoom = dash_image_zoom(dst_w, dst_h, src_w, src_h);
  obj = lv_img_create(parent);
  lv_img_set_src(obj, src);
  lv_img_set_antialias(obj, true);
  lv_img_set_zoom(obj, zoom);
  lv_obj_set_pos(obj, dash_scale_x(view, x), dash_scale_y(view, y));
  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "image object id=%u name=%s obj=%p src=%p pos=%ld,%ld zoom=%lu",
                (unsigned int)image, name, obj, src,
                (long)dash_scale_x(view, x),
                (long)dash_scale_y(view, y),
                (unsigned long)zoom);
  return obj;
}

static lv_obj_t *dash_add_image_screen(lvgl_app_page_home_view_t *view,
                                       lv_obj_t *parent,
                                       lvgl_app_image_id_t image,
                                       int32_t x,
                                       int32_t y,
                                       int32_t w,
                                       int32_t h,
