static void dash_build_root(lvgl_app_page_home_view_t *view,
                            lv_obj_t *root)
{
  lv_disp_t *disp;

  lv_obj_remove_style_all(root);
  lv_obj_set_size(root, lv_pct(100), lv_pct(100));
  lv_obj_clear_flag(root, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_scrollbar_mode(root, LV_SCROLLBAR_MODE_OFF);
  lv_obj_set_style_bg_color(root, lv_color_hex(0x03141b), 0);
  lv_obj_set_style_bg_grad_color(root, lv_color_hex(0x0b3442), 0);
  lv_obj_set_style_bg_grad_dir(root, LV_GRAD_DIR_HOR, 0);
  lv_obj_set_style_bg_opa(root, LV_OPA_COVER, 0);

  lv_obj_update_layout(root);
  view->layout_w = lv_obj_get_width(root);
  view->layout_h = lv_obj_get_height(root);

  disp = lv_disp_get_default();
  if ((view->layout_w <= 0 || view->layout_h <= 0) && disp != NULL)
    {
      view->layout_w = lv_disp_get_hor_res(disp);
      view->layout_h = lv_disp_get_ver_res(disp);
    }

  if (view->layout_w <= 0)
    {
      view->layout_w = 1024;
    }

  if (view->layout_h <= 0)
    {
      view->layout_h = 600;
    }

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "dashboard component layout %ldx%ld ref=%dx%d",
                (long)view->layout_w, (long)view->layout_h,
                DASH_REF_W, DASH_REF_H);

  view->stage = lv_obj_create(root);
  lv_obj_remove_style_all(view->stage);
  lv_obj_set_pos(view->stage, 0, 0);
  lv_obj_set_size(view->stage, view->layout_w, view->layout_h);
  lv_obj_clear_flag(view->stage, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_scrollbar_mode(view->stage, LV_SCROLLBAR_MODE_OFF);
  lv_obj_set_style_bg_opa(view->stage, LV_OPA_TRANSP, 0);

  view->background = dash_add_image(view, view->stage,
                                    LVGL_APP_IMAGE_DASHBOARD_BACKGROUND,
                                    0, 0, DASH_REF_W, DASH_REF_H,
                                    IMG_BACKGROUND_W, IMG_BACKGROUND_H);
  if (view->background != NULL)
    {
      lv_obj_move_background(view->background);
    }
}

static void lvgl_app_page_home_settings_event(lv_event_t *event)
{
  lvgl_app_page_home_view_t *view =
    (lvgl_app_page_home_view_t *)lv_event_get_user_data(event);

  if (view != NULL && view->cb.on_settings != NULL &&
      lv_event_get_code(event) == LV_EVENT_CLICKED)
    {
      view->cb.on_settings(view->user);
    }
}

int lvgl_app_page_home_view_create(lvgl_app_page_home_view_t *view,
                                   lv_obj_t *root,
                                   const lvgl_app_page_home_view_cb_t *cb,
                                   void *user)
{
  if (view == NULL || root == NULL)
    {
      return -1;
    }

  memset(view, 0, sizeof(*view));
  view->root = root;
  view->user = user;
  if (cb != NULL)
    {
      view->cb = *cb;
    }

  dash_build_root(view, root);

  dash_build_left_sidebar(view);
  dash_build_center(view);
  dash_build_right_panel(view);

#ifdef CONFIG_LVGL_APP_UI_PAGES_PAGE_HOME_INTERACTIVE_FEEDBACK
  dash_build_interaction_layer(view);
#endif

  view->content = view->stage;
  view->uptime_label = dash_add_label(view, view->stage, "运行 0s",
                                      168, 1505, 260,
                                      lv_color_hex(0xb8f8ff),
                                      DASH_FONT_CJK);

  if (view->settings_button != NULL)
    {
      lv_obj_add_event_cb(view->settings_button,
                          lvgl_app_page_home_settings_event,
                          LV_EVENT_CLICKED,
                          view);
    }

  return 0;
}

void lvgl_app_page_home_view_destroy(lvgl_app_page_home_view_t *view)
{
  if (view != NULL)
    {
      memset(view, 0, sizeof(*view));
    }
}

void lvgl_app_page_home_view_set_counter(lvgl_app_page_home_view_t *view,
                                         uint32_t counter)
{
  char text[32];

  if (view == NULL || view->counter_label == NULL)
    {
      return;
    }

  (void)snprintf(text, sizeof(text), "o CPU环形进度 %lu%%",
                 (unsigned long)(counter % 100u));
  lv_label_set_text(view->counter_label, text);
}

void lvgl_app_page_home_view_set_uptime(lvgl_app_page_home_view_t *view,
                                        uint32_t uptime_ms)
{
  char text[32];

  if (view == NULL || view->uptime_label == NULL)
    {
      return;
    }

  (void)snprintf(text, sizeof(text), "运行 %lus",
                 (unsigned long)(uptime_ms / 1000u));
  lv_label_set_text(view->uptime_label, text);
}

void lvgl_app_page_home_view_select_component(
  lvgl_app_page_home_view_t *view,
  lvgl_app_home_component_id_t component)
{
#ifdef CONFIG_LVGL_APP_UI_PAGES_PAGE_HOME_INTERACTIVE_FEEDBACK
  if (view == NULL)
    {
      return;
    }

  if (component != LVGL_APP_HOME_COMPONENT_NONE &&
      dash_find_hotspot(view, component) == NULL)
    {
      return;
    }

  dash_apply_selected_component(view, component);
#else
  (void)view;
  (void)component;
#endif
}

