static void lvgl_app_page_home_presenter_model_event(
  const lvgl_app_event_t *event,
  void *user)
{
  lvgl_app_page_home_presenter_t *presenter =
    (lvgl_app_page_home_presenter_t *)user;
  const lvgl_app_model_change_t *change;

  if (presenter == NULL || presenter->view == NULL ||
      event == NULL || event->payload == NULL ||
      event->payload_len < sizeof(*change))
    {
      return;
    }

  change = (const lvgl_app_model_change_t *)event->payload;
  if (change->key == LVGL_APP_MODEL_KEY_COUNTER &&
      change->value.type == LVGL_APP_MODEL_VALUE_UINT32)
    {
      lvgl_app_page_home_view_set_counter(presenter->view,
                                          change->value.data.u32);
    }
#ifdef CONFIG_LVGL_APP_UI_PAGES_PAGE_HOME_SHOW_UPTIME
  else if (change->key == LVGL_APP_MODEL_KEY_UPTIME_MS &&
           change->value.type == LVGL_APP_MODEL_VALUE_UINT32)
    {
      lvgl_app_page_home_view_set_uptime(presenter->view,
                                         change->value.data.u32);
    }
#endif
}

void lvgl_app_page_home_presenter_init(
  lvgl_app_page_home_presenter_t *presenter,
  lvgl_app_page_home_view_t *view)
{
  if (presenter != NULL)
    {
      presenter->view = view;
      presenter->subscribed = false;
    }
}

void lvgl_app_page_home_presenter_start(
  lvgl_app_page_home_presenter_t *presenter)
{
  lvgl_app_model_value_t value;

  if (presenter == NULL || presenter->subscribed)
    {
      return;
    }

  if (lvgl_app_data_center_get(LVGL_APP_MODEL_KEY_COUNTER, &value) == 0 &&
      value.type == LVGL_APP_MODEL_VALUE_UINT32)
    {
      lvgl_app_page_home_view_set_counter(presenter->view, value.data.u32);
    }

  if (lvgl_app_data_center_get(LVGL_APP_MODEL_KEY_UPTIME_MS, &value) == 0 &&
      value.type == LVGL_APP_MODEL_VALUE_UINT32)
    {
      lvgl_app_page_home_view_set_uptime(presenter->view, value.data.u32);
    }

  if (lvgl_app_event_bus_subscribe(
        LVGL_APP_EVENT_MODEL_CHANGED,
        lvgl_app_page_home_presenter_model_event,
        presenter,
        &presenter->model_token) == 0)
    {
      presenter->subscribed = true;
    }
}

void lvgl_app_page_home_presenter_stop(
  lvgl_app_page_home_presenter_t *presenter)
{
  if (presenter != NULL && presenter->subscribed)
    {
      (void)lvgl_app_event_bus_unsubscribe(presenter->model_token);
      presenter->subscribed = false;
    }
}

