#include <string.h>

#define EVENT_BUS_TAG "event_bus"

typedef struct
{
  bool used;
  uint16_t generation;
  lvgl_app_event_id_t id;
  lvgl_app_event_cb_t cb;
  void *user;
} lvgl_app_event_subscriber_t;

typedef struct
{
  lvgl_app_event_t event;
  uint8_t payload[CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_PAYLOAD_BYTES];
} lvgl_app_event_queue_slot_t;

static pthread_mutex_t g_event_lock = PTHREAD_MUTEX_INITIALIZER;
static lvgl_app_event_subscriber_t g_subscribers
  [CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS];
static lvgl_app_event_queue_slot_t g_queue
  [CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_QUEUE_LENGTH];
static unsigned int g_head;
static unsigned int g_tail;
static unsigned int g_count;
static bool g_initialized;

static void lvgl_app_event_bus_dispatch(const lvgl_app_event_t *event)
{
  lvgl_app_event_cb_t callbacks
    [CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS];
  void *users[CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS];
  unsigned int callback_count = 0;
  unsigned int i;

  (void)pthread_mutex_lock(&g_event_lock);
  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS; i++)
    {
      if (g_subscribers[i].used &&
          (g_subscribers[i].id == LVGL_APP_EVENT_ANY ||
           g_subscribers[i].id == event->id))
        {
          callbacks[callback_count] = g_subscribers[i].cb;
          users[callback_count] = g_subscribers[i].user;
          callback_count++;
        }
    }
  (void)pthread_mutex_unlock(&g_event_lock);

  for (i = 0; i < callback_count; i++)
    {
      callbacks[i](event, users[i]);
    }
}

int lvgl_app_event_bus_init(void)
{
  (void)pthread_mutex_lock(&g_event_lock);
  memset(g_subscribers, 0, sizeof(g_subscribers));
  memset(g_queue, 0, sizeof(g_queue));
  g_head = 0;
  g_tail = 0;
  g_count = 0;
  g_initialized = true;
  (void)pthread_mutex_unlock(&g_event_lock);

  LVGL_APP_LOGI(EVENT_BUS_TAG, "initialized");
  return 0;
}

void lvgl_app_event_bus_deinit(void)
{
  (void)pthread_mutex_lock(&g_event_lock);
  g_initialized = false;
  g_count = 0;
  (void)pthread_mutex_unlock(&g_event_lock);
}

int lvgl_app_event_bus_subscribe(lvgl_app_event_id_t id,
                                 lvgl_app_event_cb_t cb,
                                 void *user,
                                 lvgl_app_event_token_t *token)
{
  unsigned int i;

  if (cb == NULL || token == NULL)
    {
      return -EINVAL;
    }

  (void)pthread_mutex_lock(&g_event_lock);
  if (!g_initialized)
    {
      (void)pthread_mutex_unlock(&g_event_lock);
      return -ENODEV;
    }

  for (i = 0; i < CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS; i++)
    {
      if (!g_subscribers[i].used)
        {
          g_subscribers[i].used = true;
          g_subscribers[i].generation++;
          if (g_subscribers[i].generation == 0)
            {
              g_subscribers[i].generation = 1;
            }

          g_subscribers[i].id = id;
          g_subscribers[i].cb = cb;
          g_subscribers[i].user = user;
          token->slot = (uint16_t)i;
          token->generation = g_subscribers[i].generation;
          (void)pthread_mutex_unlock(&g_event_lock);
          return 0;
        }
    }

  (void)pthread_mutex_unlock(&g_event_lock);
  return -ENOSPC;
}

int lvgl_app_event_bus_unsubscribe(lvgl_app_event_token_t token)
{
  if (token.slot >= CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_MAX_SUBSCRIBERS)
    {
      return -EINVAL;
    }

  (void)pthread_mutex_lock(&g_event_lock);
  if (!g_subscribers[token.slot].used ||
      g_subscribers[token.slot].generation != token.generation)
    {
      (void)pthread_mutex_unlock(&g_event_lock);
      return -ENOENT;
    }

  g_subscribers[token.slot].used = false;
  g_subscribers[token.slot].cb = NULL;
  g_subscribers[token.slot].user = NULL;
  (void)pthread_mutex_unlock(&g_event_lock);

  return 0;
}

int lvgl_app_event_bus_publish_sync(lvgl_app_event_id_t id,
                                    const void *payload,
                                    size_t payload_len,
                                    uint32_t source)
{
  lvgl_app_event_t event;

  if (payload_len > 0 && payload == NULL)
    {
      return -EINVAL;
    }

  event.id = id;
  event.payload = payload;
  event.payload_len = payload_len;
  event.source = source;
  lvgl_app_event_bus_dispatch(&event);

  return 0;
}

int lvgl_app_event_bus_publish_async(lvgl_app_event_id_t id,
                                     const void *payload,
                                     size_t payload_len,
                                     uint32_t source)
{
  lvgl_app_event_queue_slot_t *slot;

  if (payload_len > CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_PAYLOAD_BYTES)
    {
      return -EMSGSIZE;
    }

  if (payload_len > 0 && payload == NULL)
    {
      return -EINVAL;
    }

  (void)pthread_mutex_lock(&g_event_lock);
  if (!g_initialized)
    {
      (void)pthread_mutex_unlock(&g_event_lock);
      return -ENODEV;
    }

  if (g_count >= CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_QUEUE_LENGTH)
    {
      (void)pthread_mutex_unlock(&g_event_lock);
      return -ENOSPC;
    }

  slot = &g_queue[g_tail];
  slot->event.id = id;
  slot->event.payload_len = payload_len;
  slot->event.source = source;

  if (payload_len > 0)
    {
      memcpy(slot->payload, payload, payload_len);
      slot->event.payload = slot->payload;
    }
  else
    {
      slot->event.payload = NULL;
    }

  g_tail = (g_tail + 1u) %
           CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_QUEUE_LENGTH;
  g_count++;
  (void)pthread_mutex_unlock(&g_event_lock);

  return 0;
}

int lvgl_app_event_bus_drain(unsigned int max_events)
{
  uint8_t payload[CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_PAYLOAD_BYTES];
  lvgl_app_event_t event;
  unsigned int drained = 0;

  while (drained < max_events)
    {
      (void)pthread_mutex_lock(&g_event_lock);
      if (g_count == 0)
        {
          (void)pthread_mutex_unlock(&g_event_lock);
          break;
        }

      event = g_queue[g_head].event;
      if (event.payload_len > 0)
        {
          memcpy(payload, g_queue[g_head].payload, event.payload_len);
          event.payload = payload;
        }

      g_head = (g_head + 1u) %
               CONFIG_LVGL_APP_FRAMEWORK_EVENT_BUS_QUEUE_LENGTH;
      g_count--;
      (void)pthread_mutex_unlock(&g_event_lock);

      lvgl_app_event_bus_dispatch(&event);
      drained++;
    }

  return (int)drained;
}

