static const char *dash_event_code_name(lv_event_code_t code)
{
  switch (code)
    {
      case LV_EVENT_PRESSED:
        return "PRESSED";

      case LV_EVENT_CLICKED:
        return "CLICKED";

      default:
        return "OTHER";
    }
}

static void dash_log_font_glyph(const char *scope,
                                const lv_font_t *font,
                                uint32_t codepoint,
                                const char *label)
{
  lv_font_glyph_dsc_t dsc;
  bool ok;

  if (font == NULL)
    {
      LVGL_APP_LOGW(HOME_VIEW_TAG,
                    "%s font glyph skipped font=%s cp=U+%04lx label=%s",
                    scope, DASH_FONT_CJK_NAME,
                    (unsigned long)codepoint,
                    label != NULL ? label : "");
      return;
    }

  ok = lv_font_get_glyph_dsc(font, &dsc, codepoint, 0);
  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "%s font glyph font=%s ptr=%p cp=U+%04lx label=%s ok=%d placeholder=%u resolved=%p adv=%u box=%ux%u",
                scope,
                DASH_FONT_CJK_NAME,
                font,
                (unsigned long)codepoint,
                label != NULL ? label : "",
                ok ? 1 : 0,
                (unsigned int)dsc.is_placeholder,
                dsc.resolved_font,
                (unsigned int)dsc.adv_w,
                (unsigned int)dsc.box_w,
                (unsigned int)dsc.box_h);
}

static void dash_log_cjk_font_probe(const char *scope)
{
  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "%s cjk font configured=%d name=%s ptr=%p default=%p",
                scope,
                DASH_HAS_FONT_CJK,
                DASH_FONT_CJK_NAME,
                DASH_FONT_CJK,
                lv_font_default());
  dash_log_font_glyph(scope, DASH_FONT_CJK, 0x5df2, "已");
  dash_log_font_glyph(scope, DASH_FONT_CJK, 0x9009, "选");
  dash_log_font_glyph(scope, DASH_FONT_CJK, 0x4e2d, "中");
  dash_log_font_glyph(scope, DASH_FONT_CJK, 0x65e5, "日");
  dash_log_font_glyph(scope, DASH_FONT_CJK, 0x5fd7, "志");
}

