static int32_t dash_scale_x(const lvgl_app_page_home_view_t *view,
                            int32_t value)
{
  return (int32_t)(((int64_t)value * view->layout_w + DASH_REF_W / 2) /
                   DASH_REF_W);
}

static int32_t dash_scale_y(const lvgl_app_page_home_view_t *view,
                            int32_t value)
{
  return (int32_t)(((int64_t)value * view->layout_h + DASH_REF_H / 2) /
                   DASH_REF_H);
}

