static void dash_build_interaction_layer(lvgl_app_page_home_view_t *view)
{
  unsigned int count = sizeof(g_dash_hotspots) / sizeof(g_dash_hotspots[0]);

  if (view == NULL || view->stage == NULL)
    {
      return;
    }

  view->interaction_layer = lv_obj_create(view->stage);
  lv_obj_remove_style_all(view->interaction_layer);
  lv_obj_set_pos(view->interaction_layer, 0, 0);
  lv_obj_set_size(view->interaction_layer, view->layout_w, view->layout_h);
  lv_obj_clear_flag(view->interaction_layer, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_remove_flag(view->interaction_layer, LV_OBJ_FLAG_CLICKABLE);
  lv_obj_set_scrollbar_mode(view->interaction_layer,
                            LV_SCROLLBAR_MODE_OFF);
  lv_obj_set_style_bg_opa(view->interaction_layer, LV_OPA_TRANSP, 0);

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "interaction layer created obj=%p size=%ldx%ld hotspots=%u",
                view->interaction_layer,
                (long)view->layout_w,
                (long)view->layout_h,
                count);

  dash_build_selection_box(view);

  if (count > LVGL_APP_HOME_HOTSPOT_MAX)
    {
      count = LVGL_APP_HOME_HOTSPOT_MAX;
    }

  view->hotspot_count = count;
  for (unsigned int i = 0; i < count; i++)
    {
      lvgl_app_home_hotspot_t *hotspot = &view->hotspots[i];

      hotspot->view = view;
      hotspot->id = g_dash_hotspots[i].id;
      hotspot->name = g_dash_hotspots[i].name;
      hotspot->obj = lv_obj_create(view->interaction_layer);
      dash_style_hotspot(view, hotspot->obj, &g_dash_hotspots[i]);
      LVGL_APP_LOGI(HOME_VIEW_TAG,
                    "hotspot created index=%u id=%d name=%s obj=%p pos=%ld,%ld size=%ldx%ld",
                    i,
                    (int)hotspot->id,
                    hotspot->name,
                    hotspot->obj,
                    (long)lv_obj_get_x(hotspot->obj),
                    (long)lv_obj_get_y(hotspot->obj),
                    (long)lv_obj_get_width(hotspot->obj),
                    (long)lv_obj_get_height(hotspot->obj));
      lv_obj_add_event_cb(hotspot->obj, dash_hotspot_event,
                          LV_EVENT_PRESSED, hotspot);
      lv_obj_add_event_cb(hotspot->obj, dash_hotspot_event,
                          LV_EVENT_CLICKED, hotspot);
    }

  dash_build_selection_label(view);
}
